-- 데모 차량 보증금이 시급 대비 5~7배로 너무 커서(예: 시급 15,000원인데 보증금 100,000원)
-- 짧은 시간만 빌려도 총액이 확 뛰어 보이는 문제가 있었음. 시급의 약 2배 수준으로 낮춤.
update public.vehicles set deposit_amount = 30000  where id = '00000000-0000-4000-8000-000000000001'; -- 아이오닉 5 (15,000/h)
update public.vehicles set deposit_amount = 30000  where id = '00000000-0000-4000-8000-000000000002'; -- EV6 (18,000/h)
