update public.vehicles set deposit_amount = 100000 where id = '00000000-0000-4000-8000-000000000006'; -- 타이칸 (55,000/h)
update public.vehicles set deposit_amount = 30000  where id = '00000000-0000-4000-8000-000000000007'; -- 코나 일렉트릭 (13,500/h)
update public.vehicles set deposit_amount = 30000  where id = '00000000-0000-4000-8000-000000000008'; -- 니로 EV (14,500/h)
